const [, , baseURL = "http://127.0.0.1:3217", outDir = path.join(__dirname, "out"), flag] = process.argv
const shots = flag !== "--no-shots"
fs.mkdirSync(outDir, { recursive: true })

const pages = [
  "/", "/services", "/local-growth", "/custom-systems", "/enterprise", "/pricing", "/work", "/about",
  "/contact", "/partners", "/quote", "/faq", "/insights", "/industries", "/security",
  "/web-design-nottingham", "/services/business-growth-audit", "/legal/privacy", "/does-not-exist-launch-audit",
]
const shotPages = new Set(["/", "/services", "/partners", "/contact", "/quote", "/does-not-exist-launch-audit"])
const widths = [390, 768, 1024, 1440]
const consent = { version: "3.1", functional: false, analytics: false, marketing: false, decidedAt: "2026-09-02T00:00:00.000Z" }
const slug = (p) => (p === "/" ? "home" : p.replace(/^\//, "").replace(/\//g, "_"))

async function ready(page) {
  await page.waitForFunction(() => document.documentElement.dataset.scalesmithsHydrated === "true", undefined, { timeout: 120000 }).catch(() => {})
  await page.waitForTimeout(600)
}

;(async () => {
  const browser = await chromium.launch()
  const report = { axe: {}, console: {}, status: {}, links: {}, keyboard: {}, overflow: {} }
  const internal = new Set()
  for (const width of widths) {
    const context = await browser.newContext({ viewport: { width, height: width < 768 ? 844 : 900 }, colorScheme: "dark", reducedMotion: "reduce", isMobile: width < 768, hasTouch: width < 768 })
    await context.addCookies([{ name: "ss_cookie_consent", value: encodeURIComponent(JSON.stringify(consent)), url: baseURL }])
    for (const p of pages) {
      const page = await context.newPage()
      const errors = []
      page.on("console", (m) => { if (m.type() === "error") errors.push(m.text().slice(0, 240)) })
      page.on("pageerror", (e) => errors.push("pageerror: " + e.message.slice(0, 240)))
      const res = await page.goto(baseURL + p, { waitUntil: "load", timeout: 120000 }).catch((e) => ({ status: () => "ERR " + e.message.slice(0, 80) }))
      report.status[p] = res.status()
      await ready(page)
      const key = `${p} @${width}`
      const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth)
      if (overflow > 1) report.overflow[key] = overflow
      if (shots && shotPages.has(p)) await page.screenshot({ path: path.join(outDir, `${slug(p)}-${width}.jpg`), type: "jpeg", quality: 70 })
      if (width === 1440 || width === 390) {
        await page.addScriptTag({ content: axeSource })
        const result = await page.evaluate(async () => {
          // eslint-disable-next-line no-undef
          const r = await axe.run(document, { runOnly: { type: "tag", values: ["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa", "best-practice"] } })
          return r.violations.map((v) => ({ id: v.id, impact: v.impact, n: v.nodes.length, targets: v.nodes.slice(0, 4).map((n) => n.target.join(" ") + " :: " + (n.failureSummary || "").split("\n").slice(1, 2).join(" ").slice(0, 160)) }))
        })
        if (result.length) report.axe[key] = result
        const hrefs = await page.$$eval("a[href]", (as) => as.map((a) => a.getAttribute("href")))
        for (const h of hrefs) {
          if (!h || h === "#" || h.startsWith("javascript")) { report.links[`EMPTY on ${p}`] = (report.links[`EMPTY on ${p}`] || 0) + 1; continue }
          if (h.startsWith("/") && !h.startsWith("//")) internal.add(h.split("#")[0] || "/")
        }
      }
      if (errors.length) report.console[key] = [...new Set(errors)]
      await page.close()
    }
    if (width === 390) {
      const page = await context.newPage()
      await page.goto(baseURL + "/", { waitUntil: "load" })
      await ready(page)
      await page.getByRole("button", { name: /open menu/i }).click()
      await page.waitForTimeout(500)
      if (shots) await page.screenshot({ path: path.join(outDir, `mobile-menu-390.jpg`), type: "jpeg", quality: 70 })
      report.keyboard.menuFocus = await page.evaluate(() => document.activeElement?.textContent?.trim())
      await page.keyboard.press("Escape")
      report.keyboard.afterEscape = await page.evaluate(() => document.activeElement?.getAttribute("aria-label"))
      await page.close()
    }
    if (width === 1440) {
      const page = await context.newPage()
      await page.goto(baseURL + "/", { waitUntil: "load" })
      await ready(page)
      const seq = []
      for (let i = 0; i < 12; i++) {
        await page.keyboard.press("Tab")
        seq.push(await page.evaluate(() => { const el = document.activeElement; const o = getComputedStyle(el); return `${el.tagName.toLowerCase()}:${(el.getAttribute("aria-label") || el.textContent || "").trim().slice(0, 28)} [outline ${o.outlineStyle} ${o.outlineWidth}]` }))
      }
      report.keyboard.desktopTabOrder = seq
      await page.keyboard.press("Shift+Tab")
      await page.close()
    }
    await context.close()
  }
  // link check
  const bad = {}
  for (const href of internal) {
    try {
      const r = await fetch(baseURL + href, { redirect: "manual" })
      if (r.status >= 400) bad[href] = r.status
      else if (r.status >= 300) bad[href] = `${r.status} -> ${r.headers.get("location")}`
    } catch (e) { bad[href] = "ERR " + e.message }
  }
  report.links.checked = internal.size
  report.links.nonOk = bad
  fs.writeFileSync(path.join(outDir, "report.json"), JSON.stringify(report, null, 2))
  await browser.close()
  console.log("done", outDir)
})()

